<?php include 'verifica_login.php'; include 'conexao.php'; include '_layout.php';$id=id_get('id');
if($_SERVER['REQUEST_METHOD']==='POST'){ $idc=(int)($_POST['id_concurso']??0);$nome=esc($conexao,$_POST['nome']??'');$email=esc($conexao,$_POST['email']??'');$cpf=esc($conexao,$_POST['cpf']??'');$categoria=esc($conexao,$_POST['categoria']??'');$status=esc($conexao,$_POST['status']??'');if(!$idc||$nome==='')erro('Informe o concurso e o nome.');$ok=mysqli_query($conexao,"UPDATE inscricoes SET id_concurso=$idc, nome='$nome', email='$email', cpf='$cpf', categoria='$categoria', status='$status' WHERE id_inscricao=$id");if(!$ok)erro(mysqli_error($conexao));redirect('lista_inscricoes.php');}
$r=mysqli_query($conexao,"SELECT * FROM inscricoes WHERE id_inscricao=$id");if(!$r||mysqli_num_rows($r)!==1)erro('Inscrição não encontrada.');$row=mysqli_fetch_assoc($r);$conc=mysqli_query($conexao,"SELECT id_concurso,nome FROM concursos ORDER BY nome");
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>Editar Inscrição</title><?php include 'includes_painel/head.php'; ?><?php include '_form_style.php'; ?></head><body><?php include 'includes_painel/header.php'; ?><div class="crud"><div class="card"><h1>Editar Inscrição</h1><form method="post"><div class="grid"><div class="campo"><label>Concurso</label><select name="id_concurso" required><?php while($c=mysqli_fetch_assoc($conc)):?><option value="<?=$c['id_concurso']?>" <?=($row['id_concurso']??0)==$c['id_concurso']?'selected':''?>><?=h($c['nome'])?></option><?php endwhile;?></select></div><div class="campo"><label>Nome</label><input name="nome" required value="<?=h($row['nome'])?>"></div><div class="campo"><label>CPF</label><input name="cpf" value="<?=h($row['cpf']??'')?>"></div><div class="campo"><label>E-mail</label><input type="email" name="email" value="<?=h($row['email']??'')?>"></div><div class="campo"><label>Categoria</label><input name="categoria" value="<?=h($row['categoria']??'')?>"></div><div class="campo"><label>Status</label><select name="status"><?php foreach(['pendente','aprovada','rejeitada'] as $op):?><option <?=($row['status']??'')===$op?'selected':''?>><?=$op?></option><?php endforeach;?></select></div></div><div class="acoes"><button class="btn salvar">Salvar alterações</button><a class="btn voltar" href="lista_inscricoes.php">Cancelar</a></div></form></div></div></body></html>
